const lc = (v) => String(v ?? '').trim().toLowerCase();
const firstName = (name) => String(name || '').trim().split(/\s+/)[0] || 'there';

const claudeRequest = (cfg, system, user, schema, effort) => ({
  model: cfg.claudeModel,
  max_tokens: 8000,
  fallbacks: 'default',
  system,
  messages: [{ role: 'user', content: user }],
  output_config: { effort: effort || 'medium', format: { type: 'json_schema', schema } },
});

const toDT = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return DateTime.fromMillis(Math.round((v - 25569) * 86400000), { zone: 'utc' });
  const s = String(v).trim();
  let d = DateTime.fromISO(s);
  if (!d.isValid) d = DateTime.fromJSDate(new Date(s));
  return d.isValid ? d : null;
};
const daysSince = (v) => {
  const d = toDT(v);
  return d ? DateTime.now().diff(d, 'days').days : null;
};

const cfg = $('Config').first().json;
const within = (v, days) => {
  const d = daysSince(v);
  return d !== null && d <= days;
};
const count = (arr, fn) => arr.filter(fn).length;
const list = (arr, fmt) => (arr.length ? arr.slice(0, 25).map((x) => `- ${fmt(x)}`) : ['- none']);
const avg = (nums) => (nums.length ? Math.round(nums.reduce((a, b) => a + b, 0) / nums.length) : null);

const leads = $('All Leads').all().map((i) => i.json).filter((r) => r.email);
const clients = $('All Clients').all().map((i) => i.json).filter((r) => r.email);
const checkins = $('All Check-ins').all().map((i) => i.json).filter((r) => r.email);

const newLeads = leads.filter((l) => within(l.created_at, 7));
const active = clients.filter((c) => lc(c.status) === 'active');
const newClients = clients.filter((c) => within(c.start_date, 7));
const weekCheckins = checkins.filter((c) => within(c.submitted_at, 7));
const expected = active.filter((c) => !within(c.start_date, 5));
const checkedIn = new Set(weekCheckins.map((c) => lc(c.email)));
const missing = expected.filter((c) => !checkedIn.has(lc(c.email)));
const flagged = weekCheckins.filter((c) => ['amber', 'red'].includes(lc(c.risk_level)));
const adherence = weekCheckins.map((c) => Number(c.adherence_score)).filter(Number.isFinite);

const stats = {
  new_leads: newLeads.length,
  hot: count(newLeads, (l) => lc(l.tier) === 'hot'),
  warm: count(newLeads, (l) => lc(l.tier) === 'warm'),
  cold: count(newLeads, (l) => lc(l.tier) === 'cold'),
  consults_booked_open: count(leads, (l) => lc(l.status) === 'booked'),
  new_clients: newClients.length,
  active_clients: active.length,
  checkins_received: weekCheckins.length,
  checkins_expected: expected.length,
  average_adherence: avg(adherence),
  red: count(weekCheckins, (c) => lc(c.risk_level) === 'red'),
  amber: count(weekCheckins, (c) => lc(c.risk_level) === 'amber'),
};

const system = [
  `You write the Monday morning digest for ${cfg.coachName}, who runs ${cfg.businessName}, a 1:1 online fitness coaching business.`,
  '',
  'Use only the numbers and names provided; never invent data. Plain text, under 350 words, skimmable in one minute. Structure:',
  '1. One-line headline for the week.',
  '2. Numbers: leads (hot/warm/cold), consults booked, new clients, check-in rate, average adherence.',
  '3. Who needs attention today: each amber/red client and each client who missed their check-in, with one suggested action each.',
  '4. Patterns: common struggles across clients and what that suggests for programming.',
  '5. Wins worth celebrating (first names only).',
  '6. One content idea for social media based on this week\'s most common struggle, with a one-sentence hook.',
].join('\n');

const user = [
  `Week ending ${DateTime.now().setZone(cfg.timezone).toFormat('d LLLL yyyy')}`,
  '',
  'Stats:',
  JSON.stringify(stats, null, 2),
  '',
  'Amber/red check-ins:',
  ...list(flagged, (c) => `${c.name || c.email}: ${lc(c.risk_level)}, adherence ${c.adherence_score}, reasons: ${c.risk_reasons || '-'}, notes: ${c.coach_notes || '-'}`),
  '',
  'Missed check-in this week:',
  ...list(missing, (c) => `${c.name || c.email}, last check-in ${c.last_checkin_at ? String(c.last_checkin_at).slice(0, 10) : 'never'}`),
  '',
  'Struggles reported:',
  ...list(weekCheckins.filter((c) => c.struggles), (c) => c.struggles),
  '',
  'Wins reported:',
  ...list(weekCheckins.filter((c) => c.wins), (c) => `${firstName(c.name)}: ${c.wins}`),
  '',
  'New leads:',
  ...list(newLeads, (l) => `${l.name || l.email}: ${l.tier || '?'} (${l.fit_score || '?'}), ${l.goal || '?'}, status ${l.status || '?'}`),
].join('\n');

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['subject', 'body'],
  properties: { subject: { type: 'string' }, body: { type: 'string' } },
};

return [{ json: { request: claudeRequest(cfg, system, user, schema, 'medium'), stats }, pairedItem: { item: 0 } }];

const parseClaude = (res) => {
  if (res.stop_reason === 'refusal') throw new Error('Claude declined this request: ' + JSON.stringify(res.stop_details || {}));
  if (res.stop_reason === 'max_tokens') throw new Error('Claude ran out of tokens; raise max_tokens in the matching Build node');
  const block = (res.content || []).find((b) => b.type === 'text');
  if (!block) throw new Error('Claude returned no text block: ' + JSON.stringify(res).slice(0, 500));
  return JSON.parse(block.text);
};

const ai = parseClaude($input.first().json);
return [{ json: { subject: ai.subject, body: ai.body }, pairedItem: { item: 0 } }];
